UPDATE user_room
SET last_msg_time = #{lastMsgTime},
    hidden_at     = NULL,
    update_time   = NOW()
WHERE room_id = #{roomId}
  AND user_id = #{userId}

mapper.select:
SELECT user_id, read_seq
FROM user_room
WHERE room_id = #{roomId}
  AND user_id IN
#{userId}

mapper.update:
UPDATE user_room
SET read_seq    = #{readSeq},
    update_time = NOW()
WHERE room_id = #{roomId}
  AND user_id = #{userId}
  AND read_seq < #{readSeq}

UPDATE user_room
SET hidden_at   = NOW(),
    update_time = NOW()
WHERE room_id = #{roomId}
  AND user_id = #{userId}
